DROP TABLE IF EXISTS `Screening_Answer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Screening_Answer` (
  `record_id` int NOT NULL,
  `question_id` int NOT NULL,
  `answer` tinyint(1) NOT NULL,
  `remark` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT (now()),
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`record_id`,`question_id`),
  KEY `question_id` (`question_id`),
  CONSTRAINT `Screening_Answer_ibfk_1` FOREIGN KEY (`record_id`) REFERENCES `Screening_Record` (`record_id`) ON DELETE CASCADE,
  CONSTRAINT `Screening_Answer_ibfk_2` FOREIGN KEY (`question_id`) REFERENCES `Screening_Question` (`question_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

