INSERT INTO `Screening_Question` VALUES (38,'มีประวัติแพ้ไก่หรือไข่ไก่อย่างรุนแรง / Have a history of severe allergy to chicken or chicken eggs.',1,1,'2026-07-16 14:27:11','system_seed','2026-07-17 21:35:34',NULL,NULL,NULL),(39,'เคยแพ้วัคซีนไข้หวัดใหญ่ หรือแพ้สารประกอบอื่นๆ ในวัคซีนอย่างรุนแรง / Have a history of severe allergic reaction to the influenza vaccine or any other components in the vaccine.',1,2,'2026-07-16 14:27:11','system_seed','2026-07-17 21:35:34',NULL,NULL,NULL),(40,'กำลังมีไข้ หรือกำลังเจ็บป่วยเฉียบพลัน / Currently having a fever or an acute illness.',1,3,'2026-07-16 14:27:11','system_seed','2026-07-17 21:35:34',NULL,NULL,NULL),(41,'เพิ่งหายจากการเจ็บป่วยเฉียบพลันมาไม่เกิน 7 วัน / Recovered from an acute illness within the past 7 days.',1,4,'2026-07-16 14:27:11','system_seed','2026-07-17 21:35:34',NULL,NULL,NULL),(42,'เพิ่งมานอนรักษาตัวและออกจากโรงพยาบาล ไม่เกิน 14 วัน / Discharged from inpatient hospital care within the past 14 days.',1,5,'2026-07-16 14:27:11','system_seed','2026-07-17 21:35:34',NULL,NULL,NULL),(43,'ยังมีโรคประจำตัวที่อาการกำเริบ (เช่น ใจสั่น เจ็บแน่นหน้าอก หอบเหนื่อย) หรือยังควบคุมอาการของโรคไม่ได้ / Still have an underlying disease with active/exacerbated symptoms (e.g., palpitations, chest tightness, shortness of breath) or the condition is not yet well-controlled.',1,6,'2026-07-16 14:27:11','system_seed','2026-07-17 21:35:34',NULL,NULL,NULL),(44,'กำลังตั้งครรภ์ แต่มีอายุครรภ์น้อยกว่า 4 เดือน / Currently pregnant, but with a gestational age of less than 4 months.',1,7,'2026-07-16 14:27:11','system_seed','2026-07-17 21:35:34',NULL,NULL,NULL),(45,'มีภาวะครรภ์เสี่ยงสูง หรือเคยมีภาวะแทรกซ้อนจากการตั้งครรภ์ (เช่น Toxic goiter, pre-eclampsia, eclampsia) / Have a high-risk pregnancy or a history of pregnancy complications (e.g., Toxic goiter, pre-eclampsia, eclampsia).',1,8,'2026-07-16 14:27:11','system_seed','2026-07-17 21:35:34',NULL,NULL,NULL);
